//! Decoder tests: one decode test per message kind and per tuple column kind, real wire
//! bytes captured from PostgreSQL 16.15 (wal_level=logical, pgoutput proto_version 1) with
//! `pg_logical_slot_peek_binary_changes` over a scratch table `lvsrc_dec_items`
//! (id int primary key, v text, n numeric) with REPLICA IDENTITY FULL, plus hand-built
//! bytes for the kinds the capture cannot produce (Origin, Type, the `'K'` old tuple, the
//! `'u'` unchanged-TOAST and `'b'` binary cells: PG16 fully de-TOASTs both tuples of an
//! update when the identity is FULL, so `u` never reaches the wire there).

use super::*;

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len() / 2)
        .map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap())
        .collect()
}

fn cols<'a>(t: &Tuple<'a>) -> Vec<Column<'a>> {
    let v: Vec<Column<'a>> = t.columns().map(|c| c.unwrap()).collect();
    assert_eq!(v.len(), t.len());
    v
}

fn text<'b>(v: &'b [Column<'_>], i: usize) -> &'b [u8] {
    match &v[i] {
        Column::Text(s) => s,
        other => panic!("expected Text at {i}, got {other:?}"),
    }
}

const BEGIN: &str = "420000000001b3bc7800030320a87e565200000336";
const COMMIT: &str = "43000000000001b3bc780000000001b3bca800030320a87e5652";
const RELATION: &str = "52000040687075626c6963006c767372635f6465635f6974656d73006600030169640000000017ffffffff01760000000019ffffffff016e00000006a4ffffffff";
const INSERT_PLAIN: &str = "49000040684e0003740000000131740000000568656c6c6f740000000431302e35";
const INSERT_NULLS: &str = "49000040684e00037400000001326e6e";
const INSERT_TOAST: &str = "";
const UPDATE_FULL: &str = "55000040684f0003740000000131740000000568656c6c6f740000000431302e354e0003740000000131740000000568656c6c6f740000000432302e35";
const UPDATE_TOAST: &str = "";
const DELETE_OLD: &str = "44000040684f00037400000001326e6e";
const TRUNCATE: &str = "54000000010000004068";
const MESSAGE: &str = "4d010000000001b3cf986c76737263000000000b6465632d66697874757265";

const REL: u32 = 16488;

#[test]
fn begin_real_bytes() {
    assert_eq!(
        parse(&unhex(BEGIN)).unwrap(),
        Message::Begin {
            final_lsn: 28556408,
            commit_time_us: 847863730820690,
            xid: 822,
        }
    );
}

#[test]
fn commit_real_bytes() {
    assert_eq!(
        parse(&unhex(COMMIT)).unwrap(),
        Message::Commit {
            flags: 0,
            commit_lsn: 28556408,
            end_lsn: 28556456,
            commit_time_us: 847863730820690,
        }
    );
}

#[test]
fn relation_real_bytes() {
    let bytes = unhex(RELATION);
    let m = parse(&bytes).unwrap();
    let Message::Relation(rel) = m else {
        panic!("expected Relation, got {m:?}")
    };
    assert_eq!(rel.rel_id, REL);
    assert_eq!((rel.namespace, rel.name), ("public", "lvsrc_dec_items"));
    assert_eq!(rel.replica_identity, replica_identity::FULL);
    let attrs: Vec<Attr<'_>> = rel.columns().map(|a| a.unwrap()).collect();
    assert_eq!(attrs.len(), 3);
    assert_eq!(attrs[0].name, "id");
    assert_eq!((attrs[1].name, attrs[1].type_oid), ("v", 25));
    assert_eq!((attrs[2].name, attrs[2].type_oid), ("n", 1700));
    assert!(attrs.iter().all(|a| a.key)); // every column is key under FULL
    assert!(attrs.iter().all(|a| a.type_mod == -1));
}

#[test]
fn insert_text_and_null_cells_real_bytes() {
    let bytes = unhex(INSERT_PLAIN);
    let m = parse(&bytes).unwrap();
    let Message::Insert { rel_id, new } = m else {
        panic!("expected Insert, got {m:?}")
    };
    assert_eq!(rel_id, REL);
    let c = cols(&new);
    assert_eq!(
        c,
        vec![
            Column::Text(b"1"),
            Column::Text(b"hello"),
            Column::Text(b"10.5")
        ]
    );

    let bytes = unhex(INSERT_NULLS);
    let m = parse(&bytes).unwrap();
    let Message::Insert { new, .. } = m else {
        panic!("expected Insert, got {m:?}")
    };
    assert_eq!(
        cols(&new),
        vec![Column::Text(b"2"), Column::Null, Column::Null]
    );
}

#[test]
fn insert_toasted_value_real_bytes() {
    let bytes = unhex(INSERT_TOAST);
    let m = parse(&bytes).unwrap();
    let Message::Insert { new, .. } = m else {
        panic!("expected Insert, got {m:?}")
    };
    let c = cols(&new);
    assert_eq!(text(&c, 0), b"3");
    assert_eq!(text(&c, 2), b"3");
    assert_eq!(text(&c, 1).len(), 2767); // incompressible base64 left the tuple TOASTed
    assert!(text(&c, 1).ends_with(b"g="));
}

#[test]
fn update_with_old_tuple_real_bytes() {
    let bytes = unhex(UPDATE_FULL);
    let m = parse(&bytes).unwrap();
    let Message::Update { rel_id, old, new } = m else {
        panic!("expected Update, got {m:?}")
    };
    assert_eq!(rel_id, REL);
    let (kind, old_t) = old.expect("FULL identity sends the whole old row");
    assert_eq!(kind, OldTuple::Full);
    assert_eq!(
        cols(&old_t),
        vec![
            Column::Text(b"1"),
            Column::Text(b"hello"),
            Column::Text(b"10.5")
        ]
    );
    assert_eq!(
        cols(&new),
        vec![
            Column::Text(b"1"),
            Column::Text(b"hello"),
            Column::Text(b"20.5")
        ]
    );
}

#[test]
fn update_toasted_unchanged_real_bytes() {
    // PG16 fully de-TOASTs both tuples of the update before pgoutput sees them, so the
    // unchanged toast value arrives as full text on the wire with identity FULL.
    let bytes = unhex(UPDATE_TOAST);
    let m = parse(&bytes).unwrap();
    let Message::Update { old, new, .. } = m else {
        panic!("expected Update, got {m:?}")
    };
    let (_, old_t) = old.unwrap();
    assert_eq!(text(&cols(&old_t), 1).len(), 2767);
    let c = cols(&new);
    assert_eq!(text(&c, 1).len(), 2767);
    assert_eq!(text(&c, 2), b"4");
}

#[test]
fn delete_real_bytes() {
    let bytes = unhex(DELETE_OLD);
    let m = parse(&bytes).unwrap();
    let Message::Delete { rel_id, old } = m else {
        panic!("expected Delete, got {m:?}")
    };
    assert_eq!(rel_id, REL);
    assert_eq!(old.0, OldTuple::Full);
    assert_eq!(
        cols(&old.1),
        vec![Column::Text(b"2"), Column::Null, Column::Null]
    );
}

#[test]
fn truncate_real_bytes() {
    let bytes = unhex(TRUNCATE);
    let m = parse(&bytes).unwrap();
    let Message::Truncate { options, rel_ids } = m else {
        panic!("expected Truncate, got {m:?}")
    };
    assert_eq!(options, 0);
    let ids: Vec<u32> = rel_ids.map(|o| o.unwrap()).collect();
    assert_eq!(ids, vec![REL]);
}

#[test]
fn message_real_bytes() {
    let bytes = unhex(MESSAGE);
    let m = parse(&bytes).unwrap();
    assert_eq!(
        m,
        Message::Message {
            transactional: true,
            lsn: 28561304,
            prefix: "lvsrc",
            content: b"dec-fixture",
        }
    );
}

#[test]
fn origin_synthetic() {
    // Origin only appears in cascaded replication; built to the PG16 layout
    // (8-byte LSN + NUL-terminated name).
    let mut b = vec![b'O'];
    b.extend_from_slice(&0x1234_5678_u64.to_be_bytes());
    b.extend_from_slice(b"node_7\0");
    assert_eq!(
        parse(&b).unwrap(),
        Message::Origin {
            origin_lsn: 0x1234_5678,
            name: "node_7",
        }
    );
}

#[test]
fn type_synthetic() {
    let mut b = vec![b'Y'];
    b.extend_from_slice(&16489_u32.to_be_bytes());
    b.extend_from_slice(b"public\0mytype\0");
    assert_eq!(
        parse(&b).unwrap(),
        Message::Type {
            type_oid: 16489,
            namespace: "public",
            name: "mytype",
        }
    );
}

#[test]
fn update_key_old_tuple_with_unchanged_and_binary_cells_synthetic() {
    // 'K' old tuple (identity other than FULL), 'u' unchanged-TOAST and 'b' binary cells:
    // none of them can come off this server configuration, so they are hand-built.
    let mut b = vec![b'U'];
    b.extend_from_slice(&REL.to_be_bytes());
    b.extend_from_slice(b"K");
    b.extend_from_slice(&[0x00, 0x02, b't']); // old tuple: Text("7"), Unchanged
    b.extend_from_slice(&1_u32.to_be_bytes());
    b.extend_from_slice(b"7u");
    b.extend_from_slice(b"N");
    b.extend_from_slice(&[0x00, 0x02, b't']); // new tuple: Text("7"), Binary([ab, cd])
    b.extend_from_slice(&1_u32.to_be_bytes());
    b.extend_from_slice(b"7b");
    b.extend_from_slice(&2_u32.to_be_bytes());
    b.extend_from_slice(&[0xAB, 0xCD]);
    let m = parse(&b).unwrap();
    let Message::Update { old, new, .. } = m else {
        panic!("expected Update, got {m:?}")
    };
    let (kind, old_t) = old.unwrap();
    assert_eq!(kind, OldTuple::Key);
    assert_eq!(cols(&old_t), vec![Column::Text(b"7"), Column::Unchanged]);
    assert_eq!(
        cols(&new),
        vec![Column::Text(b"7"), Column::Binary(&[0xAB, 0xCD])]
    );
}

#[test]
fn delete_key_old_tuple_synthetic() {
    let mut b = vec![b'D'];
    b.extend_from_slice(&REL.to_be_bytes());
    b.extend_from_slice(b"K\0\x01n");
    let m = parse(&b).unwrap();
    let Message::Delete { old, .. } = m else {
        panic!("expected Delete, got {m:?}")
    };
    assert_eq!(old.0, OldTuple::Key);
    assert_eq!(cols(&old.1), vec![Column::Null]);
}

#[test]
fn unsupported_kinds() {
    // Stream start/end/abort, two-phase begin-prepare, parameter status and unknown bytes.
    for kind in *b"S2ELPZ" {
        assert_eq!(
            parse(&[kind, 0, 1, 2, 3]).unwrap_err(),
            Error::Unsupported(kind)
        );
    }
}

#[test]
fn truncated_and_empty_never_panic() {
    assert_eq!(parse(&[]).unwrap_err(), Error::Truncated);
    // Every proper prefix of every fixture is an error, not a panic and not a partial ok.
    for hex in [
        BEGIN,
        COMMIT,
        RELATION,
        INSERT_PLAIN,
        INSERT_NULLS,
        INSERT_TOAST,
        UPDATE_FULL,
        UPDATE_TOAST,
        DELETE_OLD,
        TRUNCATE,
        MESSAGE,
    ] {
        let bytes = unhex(hex);
        for i in 0..bytes.len() {
            assert!(
                parse(&bytes[..i]).is_err(),
                "prefix of len {i} parsed: {hex}"
            );
        }
    }
}

#[test]
fn invalid_structures() {
    let mut b = unhex(BEGIN);
    b.push(0); // trailing byte
    assert!(matches!(parse(&b).unwrap_err(), Error::Invalid(_)));

    let mut b = unhex(RELATION);
    b[5] = 0xFF; // first namespace byte: invalid UTF-8, never a lossy copy
    assert!(matches!(parse(&b).unwrap_err(), Error::Invalid(_)));

    let mut b = vec![b'I']; // bad new-tuple tag
    b.extend_from_slice(&REL.to_be_bytes());
    b.push(b'X');
    b.extend_from_slice(&[0, 1, b'n']);
    assert!(matches!(parse(&b).unwrap_err(), Error::Invalid(_)));

    let mut b = vec![b'D']; // missing old-tuple tag
    b.extend_from_slice(&REL.to_be_bytes());
    b.push(b'N');
    assert!(matches!(parse(&b).unwrap_err(), Error::Invalid(_)));

    let mut b = vec![b'I']; // unknown tuple column kind
    b.extend_from_slice(&REL.to_be_bytes());
    b.extend_from_slice(b"N\0\x01x");
    assert!(matches!(parse(&b).unwrap_err(), Error::Invalid(_)));

    let mut b = vec![b'I']; // negative tuple column count
    b.extend_from_slice(&REL.to_be_bytes());
    b.extend_from_slice(b"N\xFF\xFF");
    assert!(matches!(parse(&b).unwrap_err(), Error::Invalid(_)));

    let mut b = vec![b'T']; // count says 2 relations, bytes for 1
    b.extend_from_slice(&2_u32.to_be_bytes());
    b.push(0);
    b.extend_from_slice(&REL.to_be_bytes());
    assert_eq!(parse(&b).unwrap_err(), Error::Truncated);
}
